// Writes the list of the shared commands, from commands.json, as Go for the manifest reader, as Go
// for the plugin SDK and as TypeScript for the plugin SDK. Run by `make lib_protocol_generate`; the generated files are committed.
import { readFileSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'

const read = (path) => readFileSync(fileURLToPath(new URL(path, import.meta.url)), 'utf8')
const write = (path, text) => writeFileSync(fileURLToPath(new URL(path, import.meta.url)), text)

const { commands } = JSON.parse(read('../commands.json'))
const HEADER =
  'Code generated by libs/protocol/tools/commands.mjs from libs/protocol/commands.json. DO NOT EDIT.'

const go = [
  `// ${HEADER}`,
  '',
  'package manifest',
  '',
  '// IsSharedCommand reports whether the full id is a shared command, which plugins handle in',
  '// contributes.handlers.',
  'func IsSharedCommand(id string) bool {',
  '\tswitch id {',
  `\tcase ${commands.map((one) => JSON.stringify(one.id)).join(', ')}:`,
  '\t\treturn true',
  '\t}',
  '\treturn false',
  '}',
  '',
  '// GetSharedCommandArguments returns the arguments the shared command of the full id takes, as',
  '// commands.json declares them once for every handler.',
  'func GetSharedCommandArguments(id string) []CommandArgument {',
  '\tswitch id {',
  ...commands
    .filter((one) => (one.arguments ?? []).length > 0)
    .flatMap((one) => [
      `\tcase ${JSON.stringify(one.id)}:`,
      '\t\treturn []CommandArgument{',
      ...one.arguments.map(
        (argument) =>
          `\t\t\t{Name: ${JSON.stringify(argument.name)}, Title: ${JSON.stringify(argument.title)}, Type: ${JSON.stringify(argument.type)}, IsRequired: ${argument.required === true}},`,
      ),
      '\t\t}',
    ]),
  '\t}',
  '\treturn nil',
  '}',
  '',
].join('\n')

/** The TypeScript of the arguments of a command. */
const getTsArguments = (one) =>
  (one.arguments ?? [])
    .map(
      (argument) =>
        `{ name: '${argument.name}', title: '${argument.title}', type: '${argument.type}', isRequired: ${argument.required === true} }`,
    )
    .join(', ')

const ts = [
  `// ${HEADER}`,
  '',
  'export interface SharedCommandArgument {',
  '  readonly name: string',
  '  readonly title: string',
  '  readonly type: string',
  '  readonly isRequired: boolean',
  '}',
  '',
  'export interface SharedCommand {',
  '  readonly id: string',
  '  readonly title: string',
  '  readonly arguments: readonly SharedCommandArgument[]',
  '}',
  '',
  '// SHARED_COMMANDS are the shared commands of the application: plugins handle them with the entries of',
  '// `contributes.handlers`. A command runs its one matching handler, or offers several as its items. The',
  '// palette asks for its arguments as it asks for those of a command of a manifest.',
  'export const SHARED_COMMANDS: readonly SharedCommand[] = [',
  ...commands.flatMap((one) => [
    `  // ${one.about[0].toUpperCase() + one.about.slice(1)}.`,
    ...((one.arguments ?? []).length === 0
      ? [`  { id: '${one.id}', title: '${one.title}', arguments: [] },`]
      : [
          '  {',
          `    id: '${one.id}',`,
          `    title: '${one.title}',`,
          `    arguments: [${getTsArguments(one)}],`,
          '  },',
        ]),
  ]),
  ']',
  '',
].join('\n')

/** The Go name of a shared command, from its title: CreateText for Create text. */
const getGoName = (one) =>
  one.title
    .split(' ')
    .map((word) => word[0].toUpperCase() + word.slice(1))
    .join('')

const sdk = [
  `// ${HEADER}`,
  '',
  'package command',
  '',
  '// The full ids of the shared commands of the application. A plugin handles one with an entry of',
  '// contributes.handlers and adds the run of its handler to its Registry under the id.',
  'const (',
  ...commands.flatMap((one) => [
    `\t// ${getGoName(one)} ${one.about}.`,
    `\t${getGoName(one)} = ${JSON.stringify(one.id)}`,
  ]),
  ')',
  '',
  '// IsSharedCommand reports whether the full id is a shared command of the application.',
  'func IsSharedCommand(id string) bool {',
  '\tswitch id {',
  `\tcase ${commands.map((one) => getGoName(one)).join(', ')}:`,
  '\t\treturn true',
  '\t}',
  '\treturn false',
  '}',
  '',
  '// ListSharedCommands lists the shared commands of the application in the order commands.json',
  '// declares them, each with the arguments the palette asks for and the host checks for every handler.',
  'func ListSharedCommands() []SharedCommand {',
  '\treturn []SharedCommand{',
  ...commands.flatMap((one) =>
    (one.arguments ?? []).length === 0
      ? [`\t\t{ID: ${getGoName(one)}, Title: ${JSON.stringify(one.title)}},`]
      : [
          `\t\t{ID: ${getGoName(one)}, Title: ${JSON.stringify(one.title)}, Arguments: []SharedCommandArgument{`,
          ...one.arguments.map(
            (argument) =>
              `\t\t\t{Name: ${JSON.stringify(argument.name)}, Title: ${JSON.stringify(argument.title)}, Type: ${JSON.stringify(argument.type)}, IsRequired: ${argument.required === true}},`,
          ),
          '\t\t}},',
        ],
  ),
  '\t}',
  '}',
  '',
].join('\n')

write('../../plugin-catalog/manifest/shared_commands.go', go)
write('../../plugin-sdk-go/command/shared_commands.go', sdk)
write('../../plugin-sdk-ts/src/commands/sharedCommands.ts', ts)
